import { Children } from "react";
import { Bar as RechartsBar, Cell, LabelList } from "recharts";
import { useTheme } from "@theme";
import { clsx } from "clsx";

import { BarProps } from "../chart.types";
import { useChart } from "../hooks/use-chart";
import { ChartClasses } from "../chart.styles";

/** Returns a relative luminance (0–1) for a 6-digit hex color string. */
const getHexLuminance = (hex: string): number => {
  const r = parseInt(hex.slice(1, 3), 16) / 255;
  const g = parseInt(hex.slice(3, 5), 16) / 255;
  const b = parseInt(hex.slice(5, 7), 16) / 255;
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};

/**
 * Picks a contrasting label color based on the bar's fill.
 * Only works for hex fills — CSS variables fall back to `lightColor`
 * (suitable for the dark categorical palette).
 */
const getInternalLabelFill = (fill: string | undefined, lightColor: string, darkColor: string) => {
  if (!fill || !fill.startsWith("#")) return lightColor;
  return getHexLuminance(fill) > 0.35 ? darkColor : lightColor;
};

const Bar = ({
  roundedCorners: roundedCornersProp,
  showInternalLabel = false,
  barIndex = 0,
  ...props
}: BarProps) => {
  const theme = useTheme();
  const {
    layout,
    type,
    roundedCorners: roundedCornersFromContext,
    showBarLabels,
    chartData,
    numCategoricalColors,
    numBars,
  } = useChart();

  const roundedCorners = roundedCornersFromContext || roundedCornersProp;
  const borderRadius = theme.toPx(theme.border.radius.sm);

  const barProps: BarProps = { ...props };

  if (type === "stacked") {
    barProps.stackId = props.stackId || "a";
  }

  if (!props.fill && Children.count(props.children) === 0) {
    if (type === "categorical") {
      barProps.children = chartData?.map((_entry, index) => {
        const colorIndex = index % numCategoricalColors;
        const colorKey = `${colorIndex + 1}Default` as keyof typeof theme.color.data.categorical;
        const color = theme.color.data.categorical[colorKey];
        return <Cell key={`cell-${index}`} fill={color} />;
      });
    } else if (type === "stacked" || type === "grouped") {
      const colorIndex = barIndex % numCategoricalColors;
      const colorKey = `${colorIndex + 1}Default` as keyof typeof theme.color.data.categorical;
      barProps.fill = theme.color.data.categorical[colorKey];
    } else {
      barProps.fill = theme.color.data.categorical["1Default"];
    }
  }

  const isBottomInStack = type === "stacked" && numBars ? barIndex === 0 : false;
  const isTopInStack = type === "stacked" && numBars ? barIndex === numBars - 1 : false;

  if (roundedCorners) {
    if (type === "stacked") {
      let radius: [number, number, number, number] = [0, 0, 0, 0];
      if (layout === "horizontal") {
        // Vertical bars
        const top = isTopInStack ? borderRadius : 0;
        const bottom = isBottomInStack ? borderRadius : 0;
        radius = [top, top, bottom, bottom];
      } else {
        // Horizontal bars
        const left = isBottomInStack ? borderRadius : 0;
        const right = isTopInStack ? borderRadius : 0;
        radius = [left, right, right, left];
      }
      barProps.radius = radius;
    } else {
      barProps.radius =
        layout === "horizontal"
          ? [borderRadius, borderRadius, 0, 0]
          : [0, borderRadius, borderRadius, 0];
    }
  } else {
    barProps.radius = 0;
  }

  let labelChild: React.ReactNode;
  if (showBarLabels && (type !== "stacked" || isTopInStack)) {
    labelChild = (
      <LabelList
        className={ChartClasses.barLabel}
        fill={theme.color.content.default}
        position={layout === "horizontal" ? "top" : "right"}
      />
    );
  }

  if (showInternalLabel) {
    const existingLabel = typeof props.label === "object" ? props.label : {};
    const labelFill = getInternalLabelFill(
      barProps.fill as string | undefined,
      theme.color.background.default,
      theme.color.content.default,
    );
    barProps.label = {
      position: "inside",
      fill: labelFill,
      className: ChartClasses.internalBarLabel,
      formatter: () => props.name,
      ...existingLabel,
    };
  }

  return (
    <RechartsBar {...barProps} className={clsx(ChartClasses.bar, barProps.className)}>
      {barProps.children}
      {labelChild}
    </RechartsBar>
  );
};

Bar.displayName = "Bar";

export default Bar;
